const and = (a, b) => (v) => a(v) && b(v);                      // divide
const on  = (project, rule) => (v) => rule(project(v));          // contramap
const validConfig = and(on((c) => c.port, (n) => n > 0 && n < 65536),
                        on((c) => c.host, (h) => h.length > 0));
const Schema = z.object({ host: z.string().min(1), port: z.number().int() })
  .refine(validConfig, { path: ['port'], message: 'invalid port' }); // reasons + path
